+async function tryLinkDir(target: string, linkPath: string): Promise<boolean> {
+  try {
+    await fs.promises.symlink(target, linkPath, process.platform === 'win32' ? 'junction' : 'dir');
+    return true;
+  } catch {
+    return false;
+  }
