+    value.iconDataUrl !== undefined &&
+    (typeof value.iconDataUrl !== 'string' ||
+      Buffer.byteLength(value.iconDataUrl, 'utf8') > MAX_ICON_DATA_URL_BYTES ||
+      !ICON_DATA_URL_RE.test(value.iconDataUrl))
